import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type OrganicSproutProps = Record<string, any>;

const OrganicSprout: React.FC<OrganicSproutProps> = ({
  backgroundColor = "#F4F1EA",
  transparentBackground = false,
  durationInSeconds = 5,
  potColor = "#C26E54",
  potRimColor = "#A65840",
  stemColor = "#6D8F5C",
  leafPrimaryColor = "#5B7A4A",
  leafSecondaryColor = "#7A9C66",
  flowerPetalColor = "#FFFFFF",
  flowerCenterColor = "#F5B942",
  growthSpeed = 1.0,
  studioLabel = "MALLOY STUDIO",
}) => {

  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Transparency Logic
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing baseline
  const s = Math.min(width, height);

  // Animation Timings
  const introDelay = 15;
  const drawFrames = 70 / growthSpeed;
  
  // Pot Animation
  const potScale = spring({ 
    frame: frame - 5, 
    fps, 
    config: { damping: 14, mass: 0.8 } 
  });

  // Stem Animation
  // Path curve approximation length is ~800. We animate offset from 800 to 0.
  const stemPathLength = 800;
  const stemProgress = interpolate(
    frame, 
    [introDelay, introDelay + drawFrames], 
    [0, 1], 
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  const strokeDashoffset = stemPathLength * (1 - stemProgress);

  // Sequential Leaf Animations based on stem progress
  const leaf1Scale = spring({ 
    frame: frame - (introDelay + drawFrames * 0.25), 
    fps, 
    config: { damping: 10, mass: 0.6 } 
  });
  const leaf2Scale = spring({ 
    frame: frame - (introDelay + drawFrames * 0.55), 
    fps, 
    config: { damping: 10, mass: 0.6 } 
  });
  const leaf3Scale = spring({ 
    frame: frame - (introDelay + drawFrames * 0.8), 
    fps, 
    config: { damping: 10, mass: 0.6 } 
  });
  const topLeafLeftScale = spring({ 
    frame: frame - (introDelay + drawFrames * 1.0), 
    fps, 
    config: { damping: 11, mass: 0.7 } 
  });
  const topLeafRightScale = spring({ 
    frame: frame - (introDelay + drawFrames * 1.05), 
    fps, 
    config: { damping: 11, mass: 0.7 } 
  });

  // Flower Animation (Blooms right after top leaves)
  const flowerScale = spring({
    frame: frame - (introDelay + drawFrames * 1.15),
    fps,
    config: { damping: 12, mass: 0.8 }
  });

  // Gentle Idle Sway post-growth
  const swayAmount = interpolate(
    frame, 
    [introDelay + drawFrames, introDelay + drawFrames + 45], 
    [0, 1], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const swayAngle = Math.sin((frame - (introDelay + drawFrames)) / 25) * 4 * swayAmount;

  // Typography Fade
  const labelOpacity = interpolate(
    frame, 
    [introDelay + drawFrames + 10, introDelay + drawFrames + 40], 
    [0, 0.4], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor, overflow: "hidden" }}>
      
      {/* Centered responsive SVG container mapping to 1000x1800 internal coordinates */}
      <div 
        style={{ 
          width: '100%', 
          height: '100%', 
          display: 'flex', 
          justifyContent: 'center', 
          alignItems: 'center',
          transition: "none"
        }}
      >
        <svg 
          viewBox="0 0 1000 1800" 
          style={{ width: '100%', height: '100%', maxWidth: '1000px', transition: "none" }}
        >
          {/* POT GROUP */}
          <g 
            transform={`translate(500, 1300) scale(${potScale})`} 
            style={{ transformOrigin: "0px 0px", transition: "none" }}
          >
            {/* Ground Shadow */}
            <ellipse cx="0" cy="85" rx="110" ry="18" fill="#000000" opacity="0.06" style={{ transition: "none" }} />
            
            {/* Main Pot Body */}
            <path 
              d="M -80 80 L 80 80 L 110 0 L -110 0 Z" 
              fill={potColor} 
              style={{ transition: "none" }} 
            />
            
            {/* Pot Rim */}
            <rect 
              x="-125" 
              y="-25" 
              width="250" 
              height="25" 
              rx="8" 
              fill={potRimColor} 
              style={{ transition: "none" }} 
            />
          </g>

          {/* SPROUT GROUP (Stem + Leaves + Flower) with sway applied from the base */}
          <g 
            transform={`rotate(${swayAngle})`} 
            style={{ transformOrigin: "500px 1280px", transition: "none" }}
          >
            {/* STEM */}
            <path 
              d="M 500 1280 C 400 1050, 600 800, 500 600" 
              fill="none" 
              stroke={stemColor} 
              strokeWidth="18" 
              strokeLinecap="round"
              strokeDasharray={stemPathLength}
              strokeDashoffset={strokeDashoffset}
              style={{ transition: "none" }}
            />

            {/* LEAF 1 (Bottom Left) */}
            <g 
              transform={`translate(470, 1120) scale(${leaf1Scale}) rotate(-35)`}
              style={{ transformOrigin: "0px 0px", transition: "none" }}
            >
              <path 
                d="M 0 0 C -40 -20, -100 -50, -130 -110 C -70 -120, -20 -70, 0 0 Z" 
                fill={leafPrimaryColor} 
                style={{ transition: "none" }}
              />
            </g>

            {/* LEAF 2 (Middle Right) */}
            <g 
              transform={`translate(510, 880) scale(${leaf2Scale}) rotate(25)`}
              style={{ transformOrigin: "0px 0px", transition: "none" }}
            >
              <path 
                d="M 0 0 C 40 -20, 100 -50, 120 -100 C 70 -110, 20 -70, 0 0 Z" 
                fill={leafSecondaryColor} 
                style={{ transition: "none" }}
              />
            </g>

            {/* LEAF 3 (Upper Right) */}
            <g 
              transform={`translate(525, 710) scale(${leaf3Scale}) rotate(15)`}
              style={{ transformOrigin: "0px 0px", transition: "none" }}
            >
              <path 
                d="M 0 0 C 35 -15, 80 -40, 100 -80 C 60 -90, 15 -55, 0 0 Z" 
                fill={leafPrimaryColor} 
                style={{ transition: "none" }}
              />
            </g>

            {/* TOP LEAF (Left) - Acts as lower sepal for flower */}
            <g 
              transform={`translate(500, 600) scale(${topLeafLeftScale}) rotate(-45)`}
              style={{ transformOrigin: "0px 0px", transition: "none" }}
            >
              <path 
                d="M 0 0 C -30 -15, -80 -40, -100 -90 C -50 -100, -15 -60, 0 0 Z" 
                fill={leafSecondaryColor} 
                style={{ transition: "none" }}
              />
            </g>

            {/* TOP LEAF (Right) - Acts as lower sepal for flower */}
            <g 
              transform={`translate(500, 600) scale(${topLeafRightScale}) rotate(30)`}
              style={{ transformOrigin: "0px 0px", transition: "none" }}
            >
              <path 
                d="M 0 0 C 35 -15, 90 -45, 110 -100 C 60 -110, 15 -65, 0 0 Z" 
                fill={leafPrimaryColor} 
                style={{ transition: "none" }}
              />
            </g>

            {/* FLOWER (Blooms at the tip of the stem) */}
            <g
              transform={`translate(500, 595) scale(${flowerScale})`}
              style={{ transformOrigin: "0px 0px", transition: "none" }}
            >
              {/* Petals arranged in a circle */}
              {[0, 72, 144, 216, 288].map((angle, i) => (
                <path
                  key={i}
                  d="M 0 -10 C 20 -30, 20 -70, 0 -80 C -20 -70, -20 -30, 0 -10 Z"
                  fill={flowerPetalColor}
                  transform={`rotate(${angle})`}
                  style={{ transition: "none" }}
                />
              ))}
              
              {/* Flower Center */}
              <circle 
                cx="0" 
                cy="0" 
                r="20" 
                fill={flowerCenterColor} 
                style={{ transition: "none" }} 
              />
            </g>
          </g>
        </svg>
      </div>

      {/* Subtle Studio Label (Safe Zone Bottom) */}
      <div 
        style={{ 
          position: 'absolute', 
          bottom: height * 0.08, 
          width: '100%', 
          textAlign: 'center', 
          fontFamily: "Inter", 
          fontWeight: 600,
          fontSize: s * 0.018, 
          letterSpacing: '0.25em', 
          color: potRimColor, 
          opacity: labelOpacity,
          transition: "none"
        }}
      >
        {studioLabel}
      </div>

    </AbsoluteFill>
  );
};

export default OrganicSprout;